-- Run from the repository root with Lua 5.4: lua5.4 bin/tests/servo_names.lua
-- lib/servo_names.lua ports gripora-configurator's src/js/ServoNames.js.
-- The expected names below are the configurator's own namesFromRules()
-- output for the aircraft rule sets the Setup Wizard used to build (Mixer.js
-- buildWizardRules(), carried here as oper,input,output,weight,weightNeg,role
-- since the wizard's mixer lib now builds the car preset), generated by
-- running ServoNames.js under Node on 2026-11-16. When the JS changes,
-- regenerate these and port the change. Also covers lib/msp_servo_names.lua's
-- wire format.

local ROOT = "src/grsuite/"

local failures, checks = 0, 0
local function check(label, ok, detail)
  checks = checks + 1
  if ok then
    print("  ok    " .. label)
  else
    failures = failures + 1
    print("  FAIL  " .. label)
    if detail then print("        " .. tostring(detail)) end
  end
end

-- lib/require.lua resolves "lib/x.lua" from the script root on the radio.
-- Here every module is loaded from src/grsuite/ instead.
package.loaded["grsuite.lib.require"] = function(path)
  local key = "grsuite." .. path:gsub("%.lua$", ""):gsub("/", ".")
  if package.loaded[key] then return package.loaded[key] end
  local mod = assert(loadfile(ROOT .. path))()
  package.loaded[key] = mod
  return mod
end

-- "oper,input,output,weight,weightNeg,role;..." to rules.
local function parseRules(text)
  local rules = {}
  for item in text:gmatch("[^;]+") do
    local f = {}
    for n in item:gmatch("[^,]+") do f[#f + 1] = tonumber(n) end
    rules[#rules + 1] = {oper = f[1], input = f[2], output = f[3], offset = 0, weight = f[4], weightNeg = f[5],
      speed = 0, curve = 0, condition = 0, role = f[6]}
  end
  return rules
end

local RULES = {
  regular = "1,1,1,1000,1000,0;1,1,2,-1000,-1000,0;1,2,3,1000,1000,0;1,3,4,1000,1000,0;1,4,27,1000,1000,0",
  regularSingleNoMotor = "1,1,1,1000,1000,0;1,2,2,1000,1000,0",
  regularFlaps2Follow = "1,1,1,1000,1000,0;1,1,2,-1000,-1000,0;1,2,3,1000,1000,0;1,3,4,1000,1000,0;1,13,5,1000,1000,0;1,13,6,1000,1000,0;2,1,5,500,500,0;2,1,6,-500,-500,0;2,13,3,0,0,1;1,4,27,1000,1000,0",
  regularFlap1 = "1,1,1,1000,1000,0;1,1,2,-1000,-1000,0;1,2,3,1000,1000,0;1,3,4,1000,1000,0;1,13,5,1000,1000,0;2,13,3,0,0,1;1,4,27,1000,1000,0",
  flaperons = "1,1,1,1000,1000,0;1,1,2,-1000,-1000,0;1,2,3,1000,1000,0;1,3,4,1000,1000,0;2,13,1,500,500,0;2,13,2,500,500,0;2,13,3,0,0,1;1,4,27,1000,1000,0",
  flaperonsNoAilerons = "1,2,1,1000,1000,0;1,3,2,1000,1000,0;1,4,27,1000,1000,0",
  vtail = "1,1,1,1000,1000,0;1,1,2,-1000,-1000,0;1,3,3,1000,1000,0;2,2,3,1000,1000,0;1,3,4,-1000,-1000,0;2,2,4,1000,1000,0;1,4,27,1000,1000,0",
  wingRudder = "1,2,1,1000,1000,0;2,1,1,1000,1000,0;1,2,2,1000,1000,0;2,1,2,-1000,-1000,0;1,3,3,1000,1000,0;1,4,27,1000,1000,0;1,4,28,1000,1000,0;2,3,27,500,500,2;2,3,28,-500,-500,2",
  wingNoYaw = "1,2,1,1000,1000,0;2,1,1,1000,1000,0;1,2,2,1000,1000,0;2,1,2,-1000,-1000,0;1,13,3,1000,1000,0;2,13,1,0,0,1;2,13,2,0,0,1;1,4,27,1000,1000,0",
  trainer = "1,2,1,1000,1000,0;1,3,2,1000,1000,0;1,4,27,1000,1000,0",
}
local names = package.loaded["grsuite.lib.require"]("lib/servo_names.lua")
local codec = package.loaded["grsuite.lib.require"]("lib/msp_servo_names.lua")

local function render(map)
  local servos = {}
  for servo in pairs(map) do servos[#servos + 1] = servo end
  table.sort(servos)
  local out = {}
  for i, servo in ipairs(servos) do out[i] = servo .. "=" .. map[servo] end
  return table.concat(out, ";")
end

local CASES = {
  {name = "regular", names = "0=L AIL;1=R AIL;2=ELEV;3=STEER"},
  {name = "regularSingleNoMotor", names = "0=AIL;1=ELEV"},
  {name = "regularFlaps2Follow", names = "0=L AIL;1=R AIL;2=ELEV;3=STEER;4=L FLAP;5=R FLAP"},
  {name = "regularFlap1", names = "0=L AIL;1=R AIL;2=ELEV;3=STEER;4=FLAP"},
  {name = "flaperons", names = "0=L FLPRN;1=R FLPRN;2=ELEV;3=STEER"},
  {name = "flaperonsNoAilerons", names = "0=ELEV;1=STEER"},
  {name = "vtail", names = "0=L AIL;1=R AIL;2=L VTAIL;3=R VTAIL"},
  {name = "wingRudder", names = "0=L ELEVON;1=R ELEVON;2=STEER"},
  {name = "wingNoYaw", names = "0=L ELEVON;1=R ELEVON;2=FLAP"},
  {name = "trainer", names = "0=ELEV;1=STEER"},
}

for _, case in ipairs(CASES) do
  local got = render(names.namesFromRules(parseRules(RULES[case.name])))
  check(case.name .. " matches the configurator", got == case.names, got)
end

-- Thrust vectoring: named after the axis, unless the servo is a surface too.
local tvRules = {
  {oper = 1, input = 2, output = 1, weight = 1000, weightNeg = 1000},
  {oper = 1, input = 28, output = 2, weight = 1000, weightNeg = 1000},
  {oper = 1, input = 29, output = 3, weight = 1000, weightNeg = 1000},
}
check("thrust-vector servos named by axis",
  render(names.namesFromRules(tvRules)) == "0=ELEV;1=TV PITCH;2=TV YAW",
  render(names.namesFromRules(tvRules)))

-- Three of a kind are numbered.
local three = {}
for s = 1, 3 do three[s] = {oper = 1, input = 3, output = s, weight = 1000, weightNeg = 1000} end
check("three of a kind numbered",
  render(names.namesFromRules(three)) == "0=STEER 1;1=STEER 2;2=STEER 3",
  render(names.namesFromRules(three)))

-- assign(): assigned servos are named (a typed name there too), a generated
-- name on a servo the mix no longer drives is cleared, a typed one is kept.
local current = {}
for s = 0, names.SERVO_COUNT - 1 do current[s] = "" end
current[3] = "MYSERVO"
current[5] = "TOWHOOK"
current[6] = "L FLAP"
current[7] = "TV ROLL"
local changed = names.assign(current, parseRules(RULES[CASES[1].name]))
check("assign names the mix",
  current[0] == "L AIL" and current[1] == "R AIL" and current[2] == "ELEV" and current[3] == "STEER",
  render(current))
check("assign keeps a typed name off the mix", current[5] == "TOWHOOK", current[5])
check("assign clears generated names off the mix", current[6] == "" and current[7] == "", current[6] .. "|" .. current[7])
check("assign reports exactly the changed servos", table.concat(changed, ",") == "0,1,2,3,6,7", table.concat(changed, ","))
check("assign again changes nothing", #names.assign(current, parseRules(RULES[CASES[1].name])) == 0)

check("isGenerated", names.isGenerated("R ELEVON") and names.isGenerated("AIL 3")
  and names.isGenerated("TV YAW") and not names.isGenerated("AILX") and not names.isGenerated("")
  and not names.isGenerated("L TOW"))

-- A pair of steering servos is front and rear (gripora-configurator
-- ServoNames.js); RUDDER, the name earlier versions gave, still counts as
-- generated so it is cleared when the mix moves on.
local steerPair = {
  {oper = 1, input = 3, output = 1, weight = 1000, weightNeg = 1000},
  {oper = 1, input = 3, output = 2, weight = -500, weightNeg = -500},
}
check("steering pair named front and rear",
  render(names.namesFromRules(steerPair)) == "0=F STEER;1=R STEER",
  render(names.namesFromRules(steerPair)))
check("legacy RUDDER names count as generated",
  names.isGenerated("RUDDER") and names.isGenerated("L RUDDER") and names.isGenerated("F STEER"))

check("withName adds the name", names.withName("Servo 1", {[0] = "L AIL"}, 0) == "Servo 1 (L AIL)")
check("withName leaves an unnamed servo", names.withName("Servo 2", {[0] = "L AIL", [1] = ""}, 1) == "Servo 2")
check("withName without names", names.withName("Servo 1", nil, 0) == "Servo 1")

-- Wire format (firmware msp.c, MSP2_GRIPORA_SERVO_NAMES / SET_SERVO_NAME)
check("clean trims, drops non-printables, caps at 8",
  codec.clean("  Elevator!xyz") == "Elevator" and codec.clean("L\1 AIL ") == "L AIL"
  and codec.clean(nil) == "" and codec.clean("ABCDEFG HIJ") == "ABCDEFG", codec.clean("ABCDEFG HIJ"))
local payload = codec.encode(2, " ELEV ")
check("encode: servo then the cleaned name", table.concat(payload, ",") == "2,69,76,69,86", table.concat(payload, ","))
check("encode: an empty name clears", table.concat(codec.encode(5, ""), ",") == "5")

local msg = codec.buildReadMessage()
local buf = {}
for i, b in ipairs(msg.simulatorResponse) do buf[i] = b end
local decoded, count = codec.decode(buf)
check("decode the simulator response", count == 24 and decoded[0] == "STEER" and decoded[3] == ""
  and decoded[4] == "" and decoded[23] == "", tostring(count) .. " " .. tostring(decoded[0]))
local full = {1, 8, 65, 66, 67, 68, 69, 70, 71, 72}
decoded = codec.decode(full)
check("decode an 8-character name", decoded[0] == "ABCDEFGH", decoded[0])

print(string.format("%d checks, %d failures", checks, failures))
os.exit(failures == 0 and 0 or 1)
